            "content": "---\n/** Places a theme-driven pattern behind the default slot. */\ntype BackgroundPreset = import(\"./presets\").BackgroundPreset;\n\ninterface Props {\n  preset: BackgroundPreset;\n  className?: string;\n  fade?: \"none\" | \"bottom\" | \"edges\" | \"radial\";\n}\n\nconst { preset, className, fade = \"none\" } = Astro.props;\n---\n\n<div class:list={[\"relative isolate overflow-hidden bg-background\", className]}>\n  <div aria-hidden=\"true\" data-df-bg-fade={fade}>\n    <div data-df-bg={preset}></div>\n  </div>\n  <div class=\"relative z-10\"><slot /></div>\n</div>\n",
