        "description": "Displays the final number in markup and animates a presentation-only value when visible.",
        "devDependencies": [],
        "files": [
          {
            "content": "---\n/**\n * Counter: Displays the final number in markup and animates a presentation-only value when visible.\n * Motion: An ease-out counter plays once in view. Changes can roll digits or count down.\n * Catalog: counter\n */\nimport { cn } from \"@designfy/components/lib/cn\";\n\ninterface Props {\n  /** Final value. */\n  value: number;\n  /** Initial value for the animation. */\n  from?: number;\n  /** Text before the number. */\n  prefix?: string;\n  /** Text after the number. */\n  suffix?: string;\n  /** Separate metric label. */\n  label?: string;\n  /** BCP 47 locale used when formatting the value. */\n  locale?: string;\n  /** Animation duration in milliseconds, bounded to 600–1200. */\n  duration?: number;\n  /** Count once in view, roll changed digits, or count down from the starting value. */\n  variant?: \"once\" | \"roll\" | \"countdown\";\n  /** Politely announce changes to the final number. */\n  live?: boolean;\n  /** Additional classes on the root element. */\n  class?: string;\n}\n\nconst {\n  value,\n  from = 0,\n  prefix = \"\",\n  suffix = \"\",\n  label,\n  locale = \"en\",\n  duration = 900,\n  variant = \"once\",\n  live = false,\n  class: className,\n} = Astro.props;\nconst formatted = Number.isFinite(value)\n  ? value.toLocaleString(locale, { maximumFractionDigits: 12 })\n  : String(value);\n---\n\n<span\n  data-site-counter\n  data-state=\"idle\"\n  data-value={value}\n  data-from={from}\n  data-duration={duration}\n  data-variant={variant}\n  lang={locale}\n  class={cn(\n    \"inline-flex max-w-full flex-col font-heading tabular-nums\",\n    className,\n  )}\n>\n  <span class=\"sr-only\" aria-live={live ? \"polite\" : undefined}\n    >{prefix}{formatted}{suffix}</span\n  >\n  <span aria-hidden=\"true\" class=\"inline-grid\">\n    <span class=\"invisible col-start-1 row-start-1\"\n      >{prefix}{formatted}{suffix}</span\n    >\n    <span class=\"col-start-1 row-start-1\"\n      >{prefix}<span data-counter-number>{formatted}</span>{suffix}</span\n    >\n  </span>\n  {\n    label && (\n      <span class=\"mt-2 font-sans text-sm text-muted-foreground\">{label}</span>\n    )\n  }\n</span>\n\n<script is:inline>\n  (() => {\n    function bind(root) {\n      const number = root.querySelector(\"[data-counter-number]\");\n      if (!number) return;\n      const target = Number(root.dataset.value);\n      const startValue = Number(root.dataset.from);\n      const duration = Math.min(\n        1200,\n        Math.max(600, Number(root.dataset.duration) || 900),\n      );\n      const format = new Intl.NumberFormat(root.lang, {\n        maximumFractionDigits: 12,\n      });\n      const final = format.format(target);\n      const reduced = window.matchMedia(\"(prefers-reduced-motion: reduce)\");\n      if (\n        reduced.matches ||\n        !Number.isFinite(target) ||\n        !Number.isFinite(startValue)\n      ) {\n        root.dataset.state = \"done\";\n        return;\n      }\n      let frame = 0;\n      function enter() {\n        if (root.dataset.variant === \"roll\") {\n          const previous = root.dataset.previous;\n          root.dataset.previous = final;\n          root.dataset.state = \"done\";\n          if (previous === undefined || previous === final || !number) return;\n          const changed = Array.from(final, (char, index) => {\n            const digit = document.createElement(\"span\");\n            digit.textContent = char;\n            digit.className = \"inline-block\";\n            if (\n              /\\d/.test(char) &&\n              char !== previous[previous.length - final.length + index]\n            ) {\n              digit.classList.add(\"animate-df-fade-up\");\n            }\n            return digit;\n          });\n          number.replaceChildren(...changed);\n          return;\n        }\n        const initial =\n          root.dataset.variant === \"countdown\"\n            ? Math.max(target, startValue)\n            : startValue;\n        const started = performance.now();\n        root.dataset.state = \"counting\";\n        function tick(now) {\n          if (!number) return;\n          const elapsed = reduced.matches\n            ? 1\n            : Math.min(1, (now - started) / duration);\n          const progress = 1 - (1 - elapsed) ** 4;\n          number.textContent =\n            elapsed === 1\n              ? final\n              : format.format(initial + (target - initial) * progress);\n          if (elapsed < 1) frame = requestAnimationFrame(tick);\n          else root.dataset.state = \"done\";\n        }\n        frame = requestAnimationFrame(tick);\n      }\n      const observer =\n        root.dataset.variant !== \"roll\" && \"IntersectionObserver\" in window\n          ? new IntersectionObserver((entries) => {\n              if (!entries.some((entry) => entry.isIntersecting)) return;\n              enter();\n              observer?.disconnect();\n            })\n          : undefined;\n      if (observer) observer.observe(root);\n      else enter();\n      return () => {\n        cancelAnimationFrame(frame);\n        observer?.disconnect();\n      };\n    }\n\n    function prepare() {\n      document\n        .querySelectorAll(\"[data-site-counter]:not([data-site-bound])\")\n        .forEach((root) => {\n          root.setAttribute(\"data-site-bound\", \"\");\n          const dispose = bind(root);\n          if (dispose)\n            document.addEventListener(\n              \"astro:before-swap\",\n              () => {\n                dispose();\n                root.removeAttribute(\"data-site-bound\");\n              },\n              { once: true },\n            );\n        });\n    }\n\n    prepare();\n    if (!document.documentElement.hasAttribute(\"data-site-counter-listener\")) {\n      document.documentElement.setAttribute(\"data-site-counter-listener\", \"\");\n      document.addEventListener(\"astro:page-load\", prepare);\n    }\n  })();\n</script>\n",
            "path": "registry/astro/counter/Counter.astro",
            "target": "counter/Counter.astro",
            "type": "registry:component"
          }
        ],
        "meta": {
          "catalog": "counter",
          "motion": true,
          "surface": "both"
        },
        "name": "counter",
