        "dependencies": [],
        "description": "Repeats the primary action in a full-width or inset band with an optional form.",
        "devDependencies": [],
        "files": [
          {
            "content": "---\n/**\n * CtaBand: Repeats the primary action in a full-width or inset band with an optional form.\n * Slots or React nodes: form, background.\n * Motion: The band reveals as one unit. A supplied background can add a slow loop.\n * Catalog: cta-band\n */\nimport { cn } from \"@designfy/components/lib/cn\";\n\ntype Action = { label: string; href: string };\n\ninterface Props {\n  /** Section heading. */\n  title: string;\n  /** Supporting sentence. */\n  lead?: string;\n  /** Heading level in the page outline. */\n  headingLevel?: 2 | 3 | 4 | 5 | 6;\n  /** Main action link. */\n  action?: Action;\n  /** Full-width band or inset composition. */\n  variant?: \"full\" | \"inset\";\n  /** Additional classes on the root element. */\n  class?: string;\n}\n\nconst {\n  title,\n  lead,\n  headingLevel = 2,\n  action,\n  variant = \"inset\",\n  class: className,\n} = Astro.props;\nconst Heading = `h${headingLevel}` as \"h2\";\n---\n\n<section\n  class={cn(\n    variant === \"inset\" ? \"df-section df-container\" : \"bg-primary/10\",\n    className,\n  )}\n>\n  <div\n    data-df-reveal=\"fade\"\n    class={cn(\n      \"relative isolate overflow-clip\",\n      variant === \"inset\"\n        ? \"rounded-2xl bg-primary/10 p-6 sm:p-10 lg:p-14\"\n        : \"df-section df-container\",\n    )}\n  >\n    {\n      Astro.slots.has(\"background\") && (\n        <div\n          aria-hidden=\"true\"\n          class=\"pointer-events-none absolute inset-0 -z-10\"\n        >\n          <slot name=\"background\" />\n        </div>\n      )\n    }\n    <div class=\"grid min-w-0 items-end gap-6 md:grid-cols-[minmax(0,1fr)_auto]\">\n      <div class=\"min-w-0\">\n        <Heading class=\"font-heading text-headline font-semibold\"\n          >{title}</Heading\n        >\n        {\n          lead && (\n            <p class=\"mt-4 max-w-2xl text-lead text-muted-foreground\">{lead}</p>\n          )\n        }\n      </div>\n      {\n        action && (\n          <a\n            href={action.href}\n            class=\"df-press inline-flex min-h-12 min-w-11 items-center justify-center rounded-lg bg-primary px-5 py-2 text-center text-sm font-semibold text-primary-foreground hover:bg-primary/90 w-full md:w-auto\"\n          >\n            {action.label}\n          </a>\n        )\n      }\n    </div>\n    {\n      Astro.slots.has(\"form\") && (\n        <div class=\"mt-6 max-w-xl\">\n          <slot name=\"form\" />\n        </div>\n      )\n    }\n  </div>\n</section>\n",
            "path": "registry/astro/cta-band/CtaBand.astro",
            "target": "cta-band/CtaBand.astro",
            "type": "registry:component"
          }
        ],
        "meta": {
          "catalog": "cta-band",
          "motion": true,
          "surface": "site"
        },
        "name": "cta-band",
        "registryDependencies": [
          "cn",
          "designfy-motion"
        ],
        "title": "Call to action band",
        "type": "registry:block"
