        "files": [
          {
            "content": "---\n/**\n * HeroCentered: Centers the page headline and action, with optional background, media and inline form.\n * Slots or React nodes: background, visual, form.\n * Motion: CSS entrance staggers headline, lead and actions before the optional media.\n * Catalog: hero-centered\n */\nimport { cn } from \"@designfy/components/lib/cn\";\n\ntype Action = { label: string; href: string };\n\ninterface Props {\n  /** Page headline. */\n  headline: string;\n  /** One sentence that supports the headline. */\n  lead: string;\n  /** Heading level. Use level one for the page hero. */\n  headingLevel?: 1 | 2;\n  /** Main call to action; the form can take its place. */\n  primaryAction?: Action;\n  /** Secondary link. */\n  secondaryAction?: Action;\n  /** Additional classes on the root element. */\n  class?: string;\n}\n\nconst {\n  headline,\n  lead,\n  headingLevel = 1,\n  primaryAction,\n  secondaryAction,\n  class: className,\n} = Astro.props;\nconst Heading = headingLevel === 1 ? \"h1\" : \"h2\";\n---\n\n<section\n  class={cn(\"relative isolate overflow-clip border-b border-border\", className)}\n>\n  {\n    Astro.slots.has(\"background\") && (\n      <div\n        aria-hidden=\"true\"\n        class=\"pointer-events-none absolute inset-0 -z-10\"\n      >\n        <slot name=\"background\" />\n      </div>\n    )\n  }\n  <div\n    class=\"df-container flex flex-col items-center py-16 text-center md:py-24 lg:py-28\"\n  >\n    <Heading class=\"max-w-[17ch] font-heading text-display font-semibold\">\n      <span class=\"sr-only\">{headline}</span>\n      <span aria-hidden=\"true\"\n        >{\n          headline\n            .split(/\\s+/)\n            .map((word, index) => (\n              <span\n                class=\"inline-block animate-df-fade-up [animation-delay:var(--word-delay)]\"\n                style={`--word-delay: ${index * 20 + \"ms\"}`}\n              >\n                {word}\n              </span>\n            ))\n            .flatMap((word, index) => (index ? [\" \", word] : [word]))\n        }</span\n      >\n    </Heading>\n    <p\n      class=\"mt-6 max-w-[52ch] animate-df-fade-up text-lead text-muted-foreground [animation-delay:80ms]\"\n    >\n      {lead}\n    </p>\n    {\n      (primaryAction || secondaryAction) && (\n        <div class=\"mt-8 flex w-full animate-df-fade-up flex-col gap-3 [animation-delay:160ms] min-[480px]:w-auto min-[480px]:flex-row\">\n          {primaryAction && (\n            <a\n              href={primaryAction.href}\n              class=\"df-press inline-flex min-h-12 min-w-11 items-center justify-center rounded-lg bg-primary px-5 py-2 text-center text-sm font-semibold text-primary-foreground hover:bg-primary/90 \"\n            >\n              {primaryAction.label}\n            </a>\n          )}\n          {secondaryAction && (\n            <a\n              href={secondaryAction.href}\n              class=\"df-press inline-flex min-h-12 min-w-11 items-center justify-center rounded-lg border border-border bg-background px-5 py-2 text-center text-sm font-semibold hover:bg-muted \"\n            >\n              {secondaryAction.label}\n            </a>\n          )}\n        </div>\n      )\n    }\n    {\n      Astro.slots.has(\"form\") && (\n        <div class=\"mt-8 w-full max-w-xl animate-df-fade-up [animation-delay:180ms]\">\n          <slot name=\"form\" />\n        </div>\n      )\n    }\n    {\n      Astro.slots.has(\"visual\") && (\n        <div class=\"mt-12 w-full max-w-5xl overflow-hidden rounded-2xl border border-border animate-df-fade-up [animation-delay:240ms]\">\n          <slot name=\"visual\" />\n        </div>\n      )\n    }\n  </div>\n</section>\n",
            "path": "registry/astro/hero-centered/HeroCentered.astro",
            "target": "hero-centered/HeroCentered.astro",
            "type": "registry:component"
          }
        ],
