        "description": "Opens with art-directed imagery or optional silent video behind the headline.",
        "devDependencies": [],
        "files": [
          {
            "content": "---\n/**\n * HeroMedia: Opens with art-directed imagery or optional silent video behind the headline.\n * Motion: The hero copy fades in, and foreground users can pause any decorative media motion.\n * Catalog: hero-media\n */\nimport { cn } from \"@designfy/components/lib/cn\";\n\ntype Action = { label: string; href: string };\ntype Image = {\n  src: string;\n  alt: string;\n  width: number;\n  height: number;\n  mobileSrc?: string;\n  position?: string;\n};\n\ninterface Props {\n  /** Page headline. */\n  headline: string;\n  /** Supporting sentence. */\n  lead: string;\n  /** Main link. */\n  primaryAction: Action;\n  /** Desktop image and optional mobile crop. Also serves as the video poster. */\n  image: Image;\n  /** Optional video source for wide screens without data saver. */\n  video?: string;\n  /** Heading level. Use one when this is the page hero. */\n  headingLevel?: 1 | 2;\n  /** Text over a scrim or within a solid panel. */\n  variant?: \"overlay\" | \"panel\";\n  /** Name of the pause control. */\n  pauseLabel?: string;\n  /** Name of the resume control. */\n  resumeLabel?: string;\n  /** Additional classes on the root element. */\n  class?: string;\n}\n\nconst {\n  headline,\n  lead,\n  primaryAction,\n  image,\n  video,\n  headingLevel = 1,\n  variant = \"overlay\",\n  pauseLabel = \"Pause background motion\",\n  resumeLabel = \"Resume background motion\",\n  class: className,\n} = Astro.props;\nconst Heading = headingLevel === 1 ? \"h1\" : \"h2\";\n---\n\n<section\n  data-site-hero-media\n  class={cn(\n    \"relative isolate flex min-h-[min(42rem,75svh)] flex-col justify-end overflow-hidden bg-muted\",\n    className,\n  )}\n>\n  <picture class=\"absolute inset-0 -z-20 block overflow-hidden\">\n    {\n      image.mobileSrc && (\n        <source srcset={image.mobileSrc} media=\"(max-width: 767px)\" />\n      )\n    }\n    <img\n      src={image.src}\n      alt={image.alt}\n      width={image.width}\n      height={image.height}\n      style={`--media-position: ${image.position ?? \"center\"}`}\n      fetchpriority=\"high\"\n      class=\"size-full object-cover object-(--media-position) motion-safe:[animation:site-media-scale_12s_var(--ease-out-quart)_both]\"\n    />\n  </picture>\n  {\n    video && (\n      <video\n        hidden\n        muted\n        loop\n        playsinline\n        aria-hidden=\"true\"\n        preload=\"none\"\n        poster={image.src}\n        data-src={video}\n        class=\"pointer-events-none absolute inset-0 -z-20 size-full object-cover [&[hidden]]:hidden!\"\n      />\n    )\n  }\n  <div\n    aria-hidden=\"true\"\n    class=\"pointer-events-none absolute inset-0 -z-10 bg-linear-to-t from-background via-background/95 to-background/15\"\n  >\n  </div>\n  <div class=\"df-container py-14 md:py-20\">\n    <div\n      class={cn(\n        \"max-w-2xl animate-df-fade-in\",\n        variant === \"panel\" && \"rounded-2xl bg-background p-6 sm:p-10\",\n      )}\n    >\n      <Heading class=\"break-words font-heading text-display font-semibold\"\n        >{headline}</Heading\n      >\n      <p class=\"mt-4 max-w-prose text-lead text-muted-foreground\">{lead}</p>\n      <a\n        href={primaryAction.href}\n        class=\"df-press inline-flex min-h-12 min-w-11 items-center justify-center rounded-lg bg-primary px-5 py-2 text-center text-sm font-semibold text-primary-foreground hover:bg-primary/90 mt-6 w-full min-[480px]:w-auto\"\n        >{primaryAction.label}</a\n      >\n    </div>\n    <button\n      hidden\n      type=\"button\"\n      data-media-pause\n      data-pause={pauseLabel}\n      data-resume={resumeLabel}\n      aria-pressed=\"false\"\n      class=\"df-press mt-4 min-h-11 min-w-11 rounded-lg bg-background px-3 text-sm [&[hidden]]:hidden!\"\n      >{pauseLabel}</button\n    >\n  </div>\n  <style is:inline>\n    @keyframes site-media-scale {\n      to {\n        transform: scale(1.05);\n      }\n    }\n  </style>\n</section>\n\n<script is:inline>\n  (() => {\n    function bind(root) {\n      const abort = new AbortController();\n      const control = root.querySelector(\"[data-media-pause]\");\n      const picture = root.querySelector(\"picture\");\n      const video = root.querySelector(\"video\");\n      const media = matchMedia(\"(min-width: 768px)\");\n      const reduced = matchMedia(\"(prefers-reduced-motion: reduce)\");\n      let visible = true;\n      let paused = false;\n      function sync() {\n        const connection = navigator.connection;\n        const videoAllowed =\n          media.matches && !reduced.matches && !connection?.saveData;\n        const active =\n          visible &&\n          !paused &&\n          !reduced.matches &&\n          !root.matches(\":hover, :focus-within\");\n        picture?.toggleAttribute(\"data-df-paused\", !active);\n        if (control) control.hidden = reduced.matches;\n        if (!video) return;\n        video.hidden = !videoAllowed || !video.getAttribute(\"src\");\n        if (videoAllowed && active) {\n          if (!video.getAttribute(\"src\") && video.dataset.src)\n            video.src = video.dataset.src;\n          video\n            .play()\n            .then(() => {\n              if (!video.paused) video.hidden = false;\n            })\n            .catch(() => {\n              video.hidden = true;\n            });\n        } else video.pause();\n      }\n      for (const name of [\n        \"pointerenter\",\n        \"pointerleave\",\n        \"focusin\",\n        \"focusout\",\n      ]) {\n        root.addEventListener(name, () => queueMicrotask(sync), {\n          signal: abort.signal,\n        });\n      }\n      control?.addEventListener(\n        \"click\",\n        () => {\n          paused = !paused;\n          control.setAttribute(\"aria-pressed\", String(paused));\n          control.textContent =\n            (paused ? control.dataset.resume : control.dataset.pause) ?? \"\";\n          sync();\n        },\n        { signal: abort.signal },\n      );\n      for (const query of [media, reduced])\n        query.addEventListener(\"change\", sync, { signal: abort.signal });\n      const observer =\n        \"IntersectionObserver\" in window\n          ? new IntersectionObserver(([entry]) => {\n              visible = entry.isIntersecting;\n              sync();\n            })\n          : undefined;\n      observer?.observe(root);\n      sync();\n      return () => {\n        abort.abort();\n        observer?.disconnect();\n        video?.pause();\n      };\n    }\n\n    function prepare() {\n      document\n        .querySelectorAll(\"[data-site-hero-media]:not([data-site-bound])\")\n        .forEach((root) => {\n          root.setAttribute(\"data-site-bound\", \"\");\n          const dispose = bind(root);\n          if (dispose)\n            document.addEventListener(\n              \"astro:before-swap\",\n              () => {\n                dispose();\n                root.removeAttribute(\"data-site-bound\");\n              },\n              { once: true },\n            );\n        });\n    }\n\n    prepare();\n    if (\n      !document.documentElement.hasAttribute(\"data-site-hero-media-listener\")\n    ) {\n      document.documentElement.setAttribute(\n        \"data-site-hero-media-listener\",\n        \"\",\n      );\n      document.addEventListener(\"astro:page-load\", prepare);\n    }\n  })();\n</script>\n",
            "path": "registry/astro/hero-media/HeroMedia.astro",
            "target": "hero-media/HeroMedia.astro",
            "type": "registry:component"
          }
        ],
        "meta": {
          "catalog": "hero-media",
          "motion": true,
          "surface": "site"
        },
        "name": "hero-media",
        "registryDependencies": [
          "cn",
          "designfy-motion"
        ],
        "title": "Media hero",
        "type": "registry:block"
