        "files": [
          {
            "content": "---\n/**\n * LogoMarquee: Displays customer or partner names in a static row or a scrolling strip.\n * Motion: An optional marquee runs at a constant speed, with a pause button and a static reduced-motion layout.\n * Catalog: logo-strip\n */\nimport { cn } from \"@designfy/components/lib/cn\";\nimport Marquee from \"@designfy/components/marquee/Marquee.astro\";\n\ntype Logo = { name: string; src?: string; width?: number; height?: number };\n\ninterface Props {\n  /** Sentence describing who the logos represent. */\n  label: string;\n  /** Authorized logos, or company names as text. */\n  items: Logo[];\n  /** Static wrapping strip or moving row. */\n  variant?: \"static\" | \"marquee\";\n  /** Accessible pause button label. */\n  pauseLabel?: string;\n  /** Accessible resume button label. */\n  resumeLabel?: string;\n  /** Additional classes on the root element. */\n  class?: string;\n}\n\nconst {\n  label,\n  items,\n  variant = \"marquee\",\n  pauseLabel = \"Pause logos\",\n  resumeLabel = \"Resume logos\",\n  class: className,\n} = Astro.props;\nconst row = variant === \"marquee\";\n---\n\n<section\n  data-df-reveal=\"fade\"\n  class={cn(\"border-y border-border py-10 md:py-12\", className)}\n>\n  <div class=\"df-container grid min-w-0 grid-cols-1 gap-6\">\n    <p class=\"text-center text-sm font-medium text-muted-foreground\">{label}</p>\n    {\n      row ? (\n        <Marquee\n          items={[]}\n          pauseLabel={pauseLabel}\n          resumeLabel={resumeLabel}\n          class=\"font-heading text-xl font-semibold text-muted-foreground\"\n        >\n          {items.map((item) => (\n            <li>\n              {item.src ? (\n                <img\n                  src={item.src}\n                  alt={item.name}\n                  width={item.width}\n                  height={item.height}\n                  class=\"h-7 w-auto max-w-36 object-contain grayscale\"\n                />\n              ) : (\n                item.name\n              )}\n            </li>\n          ))}\n        </Marquee>\n      ) : (\n        <ul\n          role=\"list\"\n          class=\"flex flex-wrap items-center justify-center gap-x-10 gap-y-4 text-center font-heading text-xl font-semibold text-muted-foreground\"\n        >\n          {items.map((item) => (\n            <li>\n              {item.src ? (\n                <img\n                  src={item.src}\n                  alt={item.name}\n                  width={item.width}\n                  height={item.height}\n                  class=\"h-7 w-auto max-w-36 object-contain grayscale\"\n                />\n              ) : (\n                item.name\n              )}\n            </li>\n          ))}\n        </ul>\n      )\n    }\n  </div>\n</section>\n",
            "path": "registry/astro/logo-marquee/LogoMarquee.astro",
            "target": "logo-marquee/LogoMarquee.astro",
            "type": "registry:component"
          }
        ],
        "meta": {
          "catalog": "logo-strip",
          "motion": true,
          "surface": "site"
        },
        "name": "logo-marquee",
        "registryDependencies": [
          "cn",
          "designfy-motion",
          "marquee"
        ],
        "title": "Logo strip",
        "type": "registry:block"
