        "files": [
          {
            "content": "/** Combines class lists while resolving conflicting Tailwind utilities. */\nimport { clsx, type ClassValue } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\n/** Merges conditional class names and keeps the last conflicting Tailwind utility. */\nexport function cn(...inputs: ClassValue[]): string {\n  return twMerge(clsx(inputs));\n}\n",
            "path": "registry/react/lib/cn.ts",
            "target": "lib/cn.ts",
            "type": "registry:lib"
          }
        ],
        "meta": {
          "motion": false,
          "surface": "both"
        },
        "name": "cn",
