        "files": [
          {
            "content": "/**\n * FeatureGrid: Presents comparable capabilities in a responsive list with small visuals and optional links.\n * Motion: Items enter in a scroll stagger and linked items respond on hover and focus.\n * Catalog: feature-grid\n */\nimport { cn } from \"@designfy/components/lib/cn\";\n\ntype Action = { label: string; href: string };\ntype Feature = {\n  title: string;\n  description: string;\n  icon?: { src: string; width: number; height: number };\n  link?: Action;\n};\n\nexport interface FeatureGridProps {\n  /** Section heading. */\n  title: string;\n  /** Supporting sentence. */\n  lead?: string;\n  /** Heading level in the page outline. */\n  headingLevel?: 2 | 3 | 4 | 5 | 6;\n  /** Features in reading order. */\n  items: Feature[];\n  /** Desktop columns or a list separated by rules. */\n  variant?: \"three\" | \"two\" | \"dividers\";\n  /** Additional classes on the root element. */\n  className?: string;\n}\n\n/** Presents comparable capabilities in a responsive list with small visuals and optional links. */\nexport function FeatureGrid({\n  title,\n  lead,\n  headingLevel = 2,\n  items,\n  variant = \"three\",\n  className,\n}: FeatureGridProps) {\n  const Heading = `h${headingLevel}` as \"h2\";\n  const ItemHeading = `h${Math.min(6, headingLevel + 1)}` as \"h3\";\n  return (\n    <section className={cn(\"df-section\", className)}>\n      <div className=\"df-container\">\n        <header data-df-reveal=\"up\" className=\"mb-10 md:mb-14\">\n          <Heading className=\"font-heading text-headline font-semibold\">\n            {title}\n          </Heading>\n          {lead && (\n            <p className=\"mt-4 max-w-2xl text-lead text-muted-foreground\">\n              {lead}\n            </p>\n          )}\n        </header>\n        <ul\n          data-df-stagger\n          className={cn(\n            \"grid gap-6\",\n            variant === \"dividers\"\n              ? \"gap-0 divide-y divide-border\"\n              : \"sm:grid-cols-2\",\n            variant === \"three\" && \"lg:grid-cols-3\",\n          )}\n        >\n          {items.map((item) => (\n            <li\n              key={item.title}\n              data-df-reveal=\"up\"\n              className={cn(\n                \"min-w-0 break-words\",\n                variant === \"dividers\"\n                  ? \"grid items-baseline gap-2 py-6 md:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)_auto] md:gap-8\"\n                  : \"border-t border-border pt-6\",\n              )}\n            >\n              <div className=\"flex min-w-0 items-center gap-3 sm:flex-wrap\">\n                {item.icon && (\n                  <img\n                    src={item.icon.src}\n                    alt=\"\"\n                    width={item.icon.width}\n                    height={item.icon.height}\n                    className={cn(\n                      \"shrink-0 object-contain\",\n                      variant === \"two\" ? \"size-10 sm:size-16\" : \"size-6\",\n                    )}\n                  />\n                )}\n                <ItemHeading className=\"text-title font-semibold\">\n                  {item.title}\n                </ItemHeading>\n              </div>\n              <p\n                className={cn(\n                  \"text-muted-foreground\",\n                  variant !== \"dividers\" && \"mt-3\",\n                )}\n              >\n                {item.description}\n              </p>\n              {item.link && (\n                <a\n                  href={item.link.href}\n                  className=\"inline-flex min-h-11 items-center font-semibold text-primary hover:underline mt-2 w-fit\"\n                >\n                  {item.link.label}\n                </a>\n              )}\n            </li>\n          ))}\n        </ul>\n      </div>\n    </section>\n  );\n}\n",
            "path": "registry/react/feature-grid/feature-grid.tsx",
            "target": "feature-grid/feature-grid.tsx",
            "type": "registry:component"
          }
        ],
